def to_internal_action_input(resource, %{name: action_name, type: action_type}, input)
    when is_map(input) do
  Map.new(input, fn {key, value} ->
    {to_internal_action_input_key(resource, action_name, action_type, key), value}
  end)
end
def to_internal_action_input(_resource, _action, input) do
  input
end

def to_internal_filter(resource, filter) when is_map(filter) do
  Map.new(filter, fn {key, value} ->
    case key_string(key) do
      "and" -> {key, map_filter_list(resource, value)}
      "or" -> {key, map_filter_list(resource, value)}
      "not" -> {key, to_internal_filter(resource, value)}
      _ -> {to_internal_field_key(resource, key), filter_value(value)}
    end
  end)
end
def to_internal_filter(resource, filters) when is_list(filters) do
  Enum.map(filters, &to_internal_filter(resource, &1))
end
def to_internal_filter(_resource, filter) do
  filter
end

def to_internal_input(resource, %{name: action_name, type: action_type}, input)
    when is_map(input) do
  Map.new(input, fn
    {key, value} when key in ["filter", :filter] -> {key, to_internal_filter(resource, value)}
    {key, value} when key in ["sort", :sort] -> {key, to_internal_sort(resource, value)}
    {key, value} -> {to_internal_input_key(resource, action_name, action_type, key), value}
  end)
end
def to_internal_input(_resource, _action, input) do
  input
end

def parse(nil) do
  {:ok, :default}
end
def parse(:default) do
  {:ok, :default}
end
def parse([]) do
  {:ok, :default}
end
def parse(list) when is_list(list) do
  list
  |> Enum.reduce_while([], fn item, acc ->
    case parse_item(item) do
      {:ok, items} -> {:cont, acc ++ items}
      {:error, _} = err -> {:halt, err}
    end
  end)
  |> case do
    {:error, _} = err -> err
    ast -> {:ok, ast}
  end
end
def parse(_) do
  {:error, err("`fields` must be a list", "invalid_fields")}
end

