def parse(timing) do
  withl(
    split: [start, stop] <- String.split(timing, " "),
    parse_start: {start, ""} <- Integer.parse(start),
    parse_stop: {stop, ""} <- Integer.parse(stop)
  ) do
    timing = %__MODULE__{start_time: start, stop_time: stop}
    {:ok, timing}
  else
    [split: _error] -> {:error, :invalid_timing}
    [parse_start: _error] -> {:error, :time_nan}
    [parse_stop: _error] -> {:error, :time_nan}
  end
end

def parse_config(config_string) do
  case Base.decode16(config_string) do
    {:ok, config} -> {:ok, config}
    :error -> {:error, :invalid_config}
  end
end

def parse_mode(mode_string) do
  case mode_string do
    "generic" -> {:ok, :generic}
    "CELP-cbr" -> {:ok, :CELP_cbr}
    "CELP-vbr" -> {:ok, :CELP_vbr}
    "AAC-lbr" -> {:ok, :AAC_lbr}
    "AAC-hbr" -> {:ok, :AAC_hbr}
    _other -> {:error, :invalid_mode}
  end
end

def parse_numeric_bool_string(string) do
  case Integer.parse(string) do
    {0, ""} -> {:ok, false}
    {1, ""} -> {:ok, true}
    _string_not_0_nor_1 -> {:error, :string_not_0_nor_1}
  end
end

def parse_numeric_hex_string(string) do
  case Integer.parse(string, 16) do
    {number, ""} -> {:ok, number}
    _string_not_hex -> {:error, :string_not_hex}
  end
end

def parse_numeric_string(string) do
  case Integer.parse(string) do
    {number, ""} -> {:ok, number}
    _string_nan -> {:error, :string_nan}
  end
end

def parse_payload_type(pt_string) do
  case Integer.parse(pt_string) do
    {pt, ""} when pt >= 0 and pt <= 127 -> {:ok, pt}
    _otherwise -> {:error, :invalid_pt}
  end
end

def parse_sprop_ps(pss) do
  pss
  |> String.split(",")
  |> Enum.reduce_while({:ok, []}, fn parameter_set, {:ok, acc} ->
    case Base.decode64(parameter_set) do
      {:ok, decoded} -> {:cont, {:ok, acc ++ [decoded]}}
      :error -> {:halt, {:error, :invalid_ps}}
    end
  end)
end

def split(origin, delim, expected_len) do
  split = String.split(origin, delim)

  cond do
    length(split) == expected_len -> {:ok, split}
    length(split) < expected_len -> {:error, :too_few_fields}
    length(split) > expected_len -> {:error, :too_many_fields}
  end
end

def refresh_entity(url, entity, options) do
  force_fetch = Keyword.get(options, :force, false)

  if force_fetch and not are_same_origin?(url, Endpoint.url()) do
    Logger.debug("Entity is external and we want a force fetch")

    case Fetcher.fetch_and_update(url, options) do
      {:ok, _activity, entity} -> {:ok, entity}
      {:error, :http_gone} -> {:error, :http_gone, entity}
      {:error, :http_not_found} -> {:error, :http_not_found, entity}
      {:error, err} -> {:error, err}
    end
  else
    {:ok, entity}
  end
end

def init(args) do
  {:ok, args}
end

def queue_pop([%{item: element} | queue]) do
  {element, queue}
end

def get_remove_object(object) do
  case object |> Utils.get_url() |> ActivityPub.fetch_object_from_url() do
    {:ok, %Member{actor: %Actor{id: person_id}}} -> {:ok, person_id}
    _ -> {:error, :remove_object_not_found}
  end
end

def remaining_attendee_capacity(
      %{maximum_attendee_capacity: maximum_attendee_capacity},
      participant_count
    )
    when is_integer(maximum_attendee_capacity) and maximum_attendee_capacity > 0 do
  maximum_attendee_capacity - participant_count
end
def remaining_attendee_capacity(
      %{maximum_attendee_capacity: _},
      _participant_count
    ) do
  nil
end

def prepare_public_key(public_key_code) do
  case :public_key.pem_decode(public_key_code) do
    [public_key_entry] -> {:ok, :public_key.pem_entry_decode(public_key_entry)}
    _ -> {:error, :pem_decode_error}
  end
end

def validate_json_response(body, headers) do
  cond do
    !content_type_matches?(headers, "application/json") -> {:error, :bad_content_type}
    !is_map(body) -> {:error, :body_not_json}
    true -> {:ok, body}
  end
end

def get_scopes do
  @global_scope |> Map.values() |> Enum.concat() |> Enum.concat([:read, :write])
end

def get_category_statistics(_parent, _params, _context) do
  {:ok, StatisticsModule.category_statistics()}
end

def lowercase_domain(email) when is_binary(email) do
  case split_email(email) do
    [user_part, domain_part] -> {:ok, "#{user_part}@#{String.downcase(domain_part)}"}
    _ -> {:error, :invalid_email}
  end
end
def lowercase_domain(_) do
  {:error, :invalid_email}
end

def cachex_spec(name, limit, default, interval, fallback \\ nil) do
  %{
    id: String.to_atom("cache_#{to_string(name)}"),
    start:
      {Cachex, :start_link,
       [
         name,
         Keyword.merge(
           cachex_options(limit, default, interval),
           fallback_options(fallback)
         )
       ]}
  }
end

